const incoming = $('2. Normalizar mensaje').first().json;
const item = $json || {};

const hasRecord = Boolean(
  item.id ||
  item['Chat ID'] ||
  item.fields
);

if (!hasRecord || Object.keys(item).length === 0) {
  return [{
    json: {
      ...incoming,
      has_pending: false
    }
  }];
}

const f = item.fields || item;

let payload = {};

try {
  payload = JSON.parse(f['Payload JSON'] || '{}');
} catch (e) {
  payload = {};
}

return [{
  json: {
    ...incoming,
    has_pending: true,
    pending_record_id: item.id || f.id,
    pending_intent: f['Intención'] || '',
    pending_step: String(f['Paso pendiente'] || '').replace(/^=/, ''),
    pending_payload: payload
  }
}];

const d = $json;
const text = (d.text || '').trim();
const payload = { ...(d.pending_payload || {}) };

let nextStep = d.pending_step;
let active = true;
let reply = '';

if (
  d.pending_intent === 'GUARDAR' &&
  d.pending_step === 'categoria_idea'
) {
  if (!text) {
    reply = 'Indícame una categoría para guardar la idea.';
  } else {
    payload.categoria = text;
    nextStep = 'listo_guardar';
    active = false;
  }
}

else if (
  d.pending_intent === 'CREAR' &&
  d.pending_step === 'extension'
) {
  const match = text.match(/(\d{2,5})/);
  const extension = match ? Number(match[1]) : null;

  if (!extension) {
    reply = 'Indícame una extensión aproximada en palabras. Por ejemplo: 800, 1200 o 2000.';
  } else {
    payload.extension = extension;
    nextStep = 'categoria';
    reply =
      `Perfecto: ${extension} palabras.\n\n` +
      `¿En qué categoría quieres guardarlo?\n\n` +
      `Por ejemplo: Escritos, Cursos o KMS.`;
  }
}

else if (
  d.pending_intent === 'CREAR' &&
  d.pending_step === 'categoria'
) {
  if (!text) {
    reply = 'Indícame una categoría para continuar.';
  } else {
    payload.categoria = text;
    nextStep = 'lineamientos_especificos';
    reply =
      `Perfecto. Lo guardaré en la categoría "${text}".\n\n` +
      `¿Quieres agregar lineamientos específicos? ` +
      `Responde con ellos o "no".`;
  }
}

else if (
  d.pending_intent === 'CREAR' &&
  d.pending_step === 'lineamientos_especificos'
) {
  const noVals = [
    'no', 'ninguno', 'ninguna', 'sin lineamientos', 'no gracias', 'nada'
  ];

  payload.lineamientos_especificos =
    noVals.includes(text.toLowerCase()) ? '' : text;

  if (!payload.extension) {
    nextStep = 'extension';
    active = true;
    reply =
      'Antes de generar el borrador me falta la extensión. ' +
      '¿Cuántas palabras quieres aproximadamente?';
  } else {
    nextStep = 'listo_generar';
    active = false;
    reply =
      `✅ Solicitud completa.\n\n` +
      `Tipo: ${payload.tipo || 'Documento'}\n` +
      `Tema: ${payload.tema || 'Sin tema'}\n` +
      `Extensión: ${payload.extension} palabras\n` +
      `Categoría: ${payload.categoria || ''}\n\n` +
      `Generaré un borrador para que lo apruebes antes de crear el documento.`;
  }
}

else if (
  d.pending_intent === 'CREAR' &&
  d.pending_step === 'aprobar_borrador'
) {
  const t = text.toLowerCase();
  const aprobar = ['aprobar','apruebo','aprobado','sí','si','ok','aceptar','acepto'].includes(t);
  const rechazar = ['rechazar','rechazo','rechazado','no','cancelar','cancelo'].includes(t);
  const cambioMatch = text.match(/^\s*(?:cambiar|cambio|cambios|modificar|modifica|revisar|revisa)\s*:?\s*(.+)$/i);

  if (aprobar) {
    nextStep = 'aprobado_documentar';
    active = false;
    payload.aprobacion_humana = true;
    payload.aprobado_en = new Date().toISOString();
    reply = '✅ Borrador aprobado. Crearé el Google Doc y registraré los metadatos.';
  } else if (rechazar) {
    nextStep = 'rechazado';
    active = false;
    payload.aprobacion_humana = false;
    payload.rechazado_en = new Date().toISOString();
    reply =
      '🛑 Borrador rechazado. No se creó ningún documento. ' +
      'Puedes iniciar una nueva solicitud cuando quieras.';
  } else if (cambioMatch && cambioMatch[1].trim()) {
    payload.solicitud_cambios = cambioMatch[1].trim();
    payload.aprobacion_humana = false;
    payload.revision_count = (Number(payload.revision_count) || 0) + 1;
    nextStep = 'solicitar_cambios';
    active = false;
    reply =
      '✏️ Entendido. Aplicaré los cambios solicitados y generaré una nueva versión para tu aprobación.';
  } else {
    nextStep = 'aprobar_borrador';
    active = true;
    reply =
      'Necesito una decisión explícita antes de crear el documento.\n\n' +
      'Responde APROBAR, RECHAZAR o CAMBIAR: seguido de tus instrucciones.';
  }
}

else {
  active = false;
  nextStep = 'cerrada';
  reply =
    'La conversación pendiente tenía un estado no reconocido. ' +
    'Ya puedes iniciar otra solicitud.';
}

return [{
  json: {
    ...d,
    updated_payload_json: JSON.stringify(payload),
    next_step: nextStep,
    active,
    reply,
    updated_at: new Date().toISOString()
  }
}];

const d=$json,t=(d.text||'').trim();let intent='DESCONOCIDA';
if(/\b(analiza|analizar|contradicci[oó]n|contradice|inconsistencia|coherencia|compara|comparar|duplicad[oa]s?)\b/i.test(t))intent='ANALIZAR';
else if(/\b(estado|pendientes?|borradores?|revisi[oó]n)\b/i.test(t)&&/\b(estado|qu[eé]|cu[aá]ntos?|mostrar|mu[eé]strame|lista|listar|pendientes?|borradores?)\b/i.test(t))intent='ESTADO';
