let tipo='Otro';if(/\bart[ií]culo\b/i.test(t))tipo='Artículo';else if(/\bpoema\b/i.test(t))tipo='Poema';else if(/\btemario\b|\bcurso\b/i.test(t))tipo='Temario';else if(/\bdefinici[oó]n\b/i.test(t))tipo='Definición';else if(/\bidea comercial\b/i.test(t))tipo='Idea comercial';else if(/\bescena\b/i.test(t))tipo='Escena narrativa';else if(/\bpropuesta\b/i.test(t))tipo='Propuesta breve';
const ext=t.match(/(\d{2,5})\s*(?:palabras?|words?)/i),extension=ext?Number(ext[1]):null;let tema=t;const sobre=t.match(/\bsobre\s+(.+)/i);if(sobre)tema=sobre[1].trim();return [{json:{...d,intent,tipo,extension,tema,original_request:t}}];

