const d = $('6A. Procesar respuesta pendiente').first().json;
const p = JSON.parse(d.updated_payload_json || '{}');

if (!p.draft_body || !p.draft_title) {
  throw new Error('No se encontró el borrador anterior para aplicar cambios.');
}
if (!p.solicitud_cambios) {
  throw new Error('No se encontraron instrucciones de cambio.');
}

const prompt =
  `Eres un asistente editorial. Revisa un borrador en español siguiendo exactamente las instrucciones del usuario. ` +
  `Devuelve exclusivamente el texto completo revisado, sin comentarios sobre el proceso, sin bloques de código y sin metadatos. ` +
  `La primera línea debe ser el título. Mantén el tema, el tipo y aproximadamente la extensión solicitada, salvo que el cambio pedido indique otra cosa.\n\n` +
  `Tipo: ${p.tipo || 'Documento'}\n` +
  `Tema: ${p.tema || ''}\n` +
  `Extensión objetivo: ${p.extension || 'No indicada'} palabras\n` +
  `Categoría: ${p.categoria || ''}\n` +
  `Lineamientos específicos originales: ${p.lineamientos_especificos || 'Ninguno'}\n\n` +
  `INSTRUCCIONES DE CAMBIO DEL USUARIO:\n${p.solicitud_cambios}\n\n` +
  `BORRADOR ANTERIOR:\n${p.draft_title}\n\n${p.draft_body}\n\n` +
  `No inventes hechos, fuentes o citas. El resultado sigue siendo un borrador sujeto a aprobación humana.`;

const gemini_body = JSON.stringify({
  contents: [{ parts: [{ text: prompt }] }],
  generationConfig: { temperature: 0.6, maxOutputTokens: 8192 }
});

return [{
  json: {
    chat_id: d.chat_id,
    pending_record_id: d.pending_record_id,
    payload: p,
    prompt,
    gemini_body,
    revised_at: new Date().toISOString()
  }
}];

const source = $('10D. Construir prompt de cambios').first().json;
const p = { ...(source.payload || {}) };

const text = ($json.candidates?.[0]?.content?.parts || [])
  .map(part => part.text || '')
  .join('\n')
  .trim();

if (!text) {
  throw new Error('Gemini no devolvió contenido para la versión revisada.');
}

const lines = text.split(/\r?\n/).map(x => x.trim()).filter(Boolean);
const title = (lines[0] || `${p.tipo || 'Documento'}: ${p.tema || 'Sin tema'}`)
  .replace(/^#+\s*/, '')
  .slice(0, 180);
const body = (lines.length > 1 ? lines.slice(1).join('\n\n') : text).trim();
const words = (body.match(/\S+/g) || []).length;

p.draft_title = title;
p.draft_body = body;
p.draft_word_count = words;
p.draft_created_at = source.revised_at;
p.aprobacion_humana = false;
p.ultima_solicitud_cambios = p.solicitud_cambios || '';
delete p.solicitud_cambios;

const esc = value => String(value || '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const previewRaw = body.length > 1200 ? body.slice(0, 1200) + '…' : body;
const message =
  `<b>✏️ NUEVA VERSIÓN GENERADA</b>\n\n` +
  `<b>Revisión:</b> ${Number(p.revision_count) || 1}\n` +
  `<b>Título:</b> ${esc(title)}\n` +
  `<b>Extensión:</b> ${words} palabras\n\n` +
  `${esc(previewRaw)}\n\n` +
  `<b>⚠️ IMPORTANTE: si vuelves a solicitar CAMBIOS, se realizará otra llamada a Gemini y se consumirán tokens adicionales.</b>\n\n` +
  `Responde:\n` +
  `• <b>APROBAR</b> para crear el Google Doc\n` +
  `• <b>RECHAZAR</b> para descartarlo\n` +
  `• <b>CAMBIAR:</b> seguido de nuevas instrucciones`;

return [{
  json: {
    chat_id: source.chat_id,
    pending_record_id: source.pending_record_id,
    payload_json: JSON.stringify(p),
    review_message: message,
    now: new Date().toISOString()
  }
}];

